#include <utility>
#include <functional>

extern struct S s;

void f(S&&){}

int main() {
  f(std::move(s));
  std::invoke(f, std::move(s));
}

template<class F, class... Args>
  constexpr invoke_result_t<F, Args...> invoke(F&& f, Args&&... args)
    noexcept(is_nothrow_invocable_v<F, Args...>);

#include <utility>
#include <functional>

using T = struct U[];

extern T t;

void g(T&&){}

int main() {
  g(std::move(t));
  std::invoke(g, std::move(t));
}
